{"path":"/tmp/sv-840b250312154241b0297f67eae2b8ca/Program.cs","file_text":"// A package collection tool produced this report. Plain data — it carries no output formatting.

using Markout;

var pkg = new PackageReport
{
    Id = "Serilog",
    Downloads = 500_000_000,
    Dependencies = new() { new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" } },
    Diagnostics = new() { new() { Level = "warning", Text = "transitive version conflict" } },
};

// One model, three renderings. Section presence is chosen at serialize time via
// IncludeSections — omitted sections are never emitted, not hand-written.

// 1. Quiet: title + scalars only. An empty include set suppresses every detail section.
Render("QUIET", new() { IncludeSections = new() });

// 2. Diagnostics only: naming the deepest/most expensive section promotes the effective
//    verbosity so Diagnostics (Level 2) is collected and rendered, while the shallower
//    Dependencies (Level 1) stays out — selection is by name, not by level threshold.
Render("DIAGNOSTICS", new() { IncludeSections = new() { "Diagnostics" } });

// 3. Detailed: both detail sections.
Render("DETAILED", new() { IncludeSections = new() { "Dependencies", "Diagnostics" } });

void Render(string label, MarkoutWriterOptions options)
{
    Console.WriteLine($"<!-- {label} -->");
    MarkoutSerializer.Serialize(pkg, Console.Out, PackageReportContext.Default, options);
    Console.WriteLine();
}

[MarkoutSerializable(TitleProperty = nameof(Id))]
public sealed class PackageReport
{
