// A package collection tool produced this report. Plain data — it carries no output formatting.
//
// One model definition (PackageReport) drives three renders. Two axes stay separate:
//   * VERBOSITY decides which (expensive) detail sections get *collected* into the model.
//   * IncludeSections decides which collected sections get *rendered* at serialize time.
// Targeting a section by name promotes the effective verbosity to that section's collection
// level, so its data is gathered — even if we then render only that one section.

using Markout;

// Verbosity ordered by collection cost. Diagnostics is the deepest/most expensive detail.
Verbosity RequiredFor(string section) => section switch
{
    Sections.Dependencies => Verbosity.Dependencies,
    Sections.Diagnostics => Verbosity.Diagnostics,
    _ => Verbosity.Quiet,
};

// Targeting sections by name PROMOTES the effective verbosity to the highest level any
// requested section needs, so that section's data is actually collected.
Verbosity Promote(params string[] targets)
{
    var effective = Verbosity.Quiet;
    foreach (var t in targets)
        if (RequiredFor(t) > effective)
            effective = RequiredFor(t);
    return effective;
}

// Collection step: only gather a detail section when the effective verbosity reaches its
// level. Higher verbosity collects the cheaper details too.
PackageReport Collect(Verbosity effective) => new()
{
    Id = "Serilog",
    Downloads = 500_000_000,
    Dependencies = effective >= Verbosity.Dependencies
        ? new() { new() { Name = "Serilog.Sinks.Console", Version = "5.0.0" } }
        : new(),
    Diagnostics = effective >= Verbosity.Diagnostics
        ? new() { new() { Level = "warning", Text = "transitive version conflict" } }
        : new(),
};

// Render step: collect at the promoted verbosity, then select rendered sections by name.
void Report(string label, params string[] renderSections)
{
    var effective = Promote(renderSections);
    var pkg = Collect(effective);
    var options = new MarkoutWriterOptions
    {
        // An empty set renders zero sections; a populated set renders only those named —
        // even when other collected sections still hold data.
        IncludeSections = new(renderSections),
    };

    Console.WriteLine($"<!-- {label} (effective verbosity: {effective}) -->");
    Console.WriteLine(MarkoutSerializer.Serialize(pkg, PackageReportContext.Default, options));
    Console.WriteLine();
}

// 1. Quiet: title + scalars only, no detail sections collected or rendered.
Report("quiet");

// 2. Diagnostics only: naming Diagnostics promotes verbosity so it is collected (which also
//    collects the cheaper Dependencies), yet only Diagnostics renders — not Dependencies.
Report("diagnostics only", Sections.Diagnostics);

// 3. Detailed: render both detail sections.
Report("detailed", Sections.Dependencies, Sections.Diagnostics);

